<template><section class="panel"><div class="panel-title"><h2>감사 로그</h2><button type="button" @click="loadAuditLogs">조회</button></div><div class="filters"><label>운영자 ID <input v-model="auditSearch.operatorId"></label><label>행위 <input v-model="auditSearch.actionType"></label><label>대상 유형 <input v-model="auditSearch.targetType"></label><label>대상 ID <input v-model="auditSearch.targetId"></label></div><pre class="detail">{{pretty(auditResult)}}</pre>
<section class="cpf-panel"><div class="panel-title"><h3>감사 전달 복구</h3><button type="button" @click="loadAuditDeliveries">전달 상태 조회</button></div><div class="filters"><label>상태<select v-model="auditDeliveryState"><option value="">전체</option><option>PENDING</option><option>RETRY</option><option>FAILED</option><option>DELIVERED</option></select></label><label>재처리 사유<input v-model.trim="auditRetryReason"></label></div><table class="cpf-table"><thead><tr><th>ID</th><th>행위</th><th>운영자</th><th>작업</th><th>전달</th><th>시도</th><th>오류</th><th>조치</th></tr></thead><tbody><tr v-for="row in auditDeliveries" :key="row.DELIVERY_ID"><td>{{row.DELIVERY_ID}}</td><td>{{row.ACTION_TYPE}}</td><td>{{row.OPERATOR_ID}}</td><td>{{row.OPERATION_STATUS}}</td><td>{{row.DELIVERY_STATUS}}</td><td>{{row.ATTEMPT_COUNT}}/{{row.MAX_ATTEMPTS}}</td><td>{{row.LAST_ERROR}}</td><td><button v-if="['PENDING','RETRY','FAILED'].includes(row.DELIVERY_STATUS) && permission('AUDIT_LOG').writeAllowed" @click="retryAuditDelivery(row.DELIVERY_ID)">재처리</button></td></tr></tbody></table></section></section></template>
